{
  "headline": "FDA's records trace our diazepam supply to a plant classified OAI 2987 days before the posting",
  "headline_cites": ["E6", "E8"],
  "sentences": [
    {
      "text": "Diazepam is not on FDA's drug shortage list as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Both Corvale East and Corvale General hold diazepam 10 mg tablets labeled by ASCLEMED USA INC. with NDC 76420031610.",
      "cites": ["E1", "E2"]
    },
    {
      "text": "The label identifies the plant as ASCLEMED USA INC. DBA ENOVACHEM (FEI 3001452204), a registered plant.",
      "cites": ["E8"]
    },
    {
      "text": "FDA inspection 1067059 at that plant ended 2018-09-27 and was classified OAI, with a known date of 2018-12-26.",
      "cites": ["E6"]
    },
    {
      "text": "A Warning Letter was issued to the same plant on 2019-06-11.",
      "cites": ["E7"]
    },
    {
      "text": "The most recent inspection at the plant was NAI on 2025-03-05.",
      "cites": ["E8"]
    },
    {
      "text": "The recommended action is to transfer 33 tablets of 10 mg from Corvale General to Corvale East, which would give Corvale East 10 days on hand while Corvale General retains 14 days.",
      "cites": ["D4"]
    }
  ]
}
